const crypto = require('crypto');
const secret = $env.LENDLOOP_WEBHOOK_SECRET;
const ts = $json.headers['x-lendloop-timestamp'];
const sig = $json.headers['x-lendloop-signature'] || '';
const bodyStr = JSON.stringify($json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(`${ts}.${bodyStr}`).digest('hex');
const ok = sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
if (!ok || Math.abs(Date.now() / 1000 - Number(ts)) > 300) throw new Error('Invalid webhook signature');
const e = $json.body;
const texts = {
  created: `New borrow request for "${e.toolName}" (${e.startDate} to ${e.endDate}).`,
  approved: `Your request for "${e.toolName}" was approved.`,
  declined: `Your request for "${e.toolName}" was declined.`,
  returned: `"${e.toolName}" was marked as returned. Thanks!`,
};
const message = texts[e.event] || `Update on "${e.toolName}".`;
console.log(`[LendLoop notification] to=${e.recipient.email} eventId=${e.eventId} :: ${message}`);
return [{ json: { to: e.recipient.email, name: e.recipient.name, eventId: e.eventId, message } }];
